import ast
import os
import subprocess
import sys
import tempfile
import time
import tomllib
import unittest
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import from artifacts module (assumed available in environment)
try:
    from hae.evaluation.artifacts import (
        filter_bundle,
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        partition_bundle,
        count_source_files
    )
except ImportError:
    # Fallback definitions if artifacts module is not yet available or import fails
    # These match the spec provided in the prompt for hae/evaluation/artifacts.py
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Tuple[str, ...] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if any(path.endswith(s) for s in suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = len([g for g in evaluated if g.passed])
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append("Gates:")
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"  [{status_icon}] {g.name}: {g.status} ({g.method}) - {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    blocks = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        # Look for start of code block
        if line.strip().startswith("```"):
            # Extract language and potential filename
            header = line.strip()[3:].strip()
            parts = header.split()
            lang = parts[0] if parts else ""
            filename = parts[1] if len(parts) > 1 else None

            # If no filename in header, look for a comment in the first line of content
            content_lines = []
            i += 1
            while i < len(lines) and not lines[i].strip().startswith("```"):
                content_lines.append(lines[i])
                i += 1

            # Skip closing ```
            if i < len(lines):
                i += 1

            content = "\n".join(content_lines)

            # Determine path
            path = None
            if filename:
                path = filename
            elif lang == "python" and content_lines:
                # Try to find a path comment like # path: src/foo.py
                for cl in content_lines[:5]:
                    if cl.strip().startswith("# path:"):
                        path = cl.strip()[7:].strip()
                        break
                    if cl.strip().startswith("# file:"):
                        path = cl.strip()[7:].strip()
                        break

            if path:
                # Sanitize path
                clean_path = sanitize_path(path)
                if clean_path:
                    blocks[clean_path] = content
        else:
            i += 1

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = None
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            if hasattr(workspace, 'get_bundle'):
                try:
                    bundle = workspace.get_bundle()
                    source = 'workspace'
                except Exception:
                    pass
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                # Assume it's a dict-like or has a files attribute
                try:
                    bundle = workspace.files
                    source = 'workspace'
                except Exception:
                    pass

        if bundle is None and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if bundle is None:
            bundle = {}
            source = 'empty'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        filtered_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(filtered_bundle)
        python_files = count_source_files(filtered_bundle, ('.py',))

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to disk
            for path, content in filtered_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=filtered_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, ('.py',))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source,
            harness_version='3.0-execution'
        )

    def _get_python_files(self, workdir: str, authored: Dict[str, str]) -> List[str]:
        """Returns list of relative paths to .py files in authored bundle."""
        return [p for p in authored if p.endswith('.py')]

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = self._get_python_files(workdir, authored)

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        errors = []
        for rel_path in py_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{rel_path}: {e}")
            except Exception as e:
                errors.append(f"{rel_path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='; '.join(errors),
                duration_s=duration,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast.parse',
            detail=f"Validated {len(py_files)} files",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No packaging metadata found (pyproject.toml, setup.py, setup.cfg)',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='tomllib.validate',
                        detail='pyproject.toml missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='tomllib.validate',
                    detail=f'Invalid pyproject.toml: {e}',
                    duration_s=time.time() - start
                )

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)

            # Run pip install -e .
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            if result.returncode != 0:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration,
                    evidence={'stdout': result.stdout, 'stderr': result.stderr}
                )

            return GateResult(
                name='build',
                status=PASSED,
                method='pip_install',
                detail='Package installed successfully',
                duration_s=duration
            )

        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            # If pip is not available or other error, we might skip or fail?
            # Spec says: "run pip install ... when pip is available". 
            # If pip is not available, we can't evaluate build fully via execution.
            # However, we validated metadata. 
            # "A gate that could not be evaluated returns SKIPPED"
            # But if metadata is valid, is it skipped? 
            # The spec says "must exist and be valid/installable". 
            # If we can't install, we can't verify installability.
            # Let's treat missing pip as SKIPPED for the install part, but we already checked metadata.
            # Actually, if pip is missing, we can't run the install command.
            # Let's return SKIPPED if pip is not found, assuming metadata check passed.
            if "No module named pip" in str(e) or "pip" in str(e).lower():
                 return GateResult(
                    name='build',
                    status=SKIPPED,
                    method='pip_install',
                    detail='pip not available',
                    duration_s=time.time() - start
                )
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'Error running pip: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test modules
        # "Non-test authored modules"
        # Exclude test files: "test" in basename.lower()
        modules = []
        for rel_path in authored:
            if not rel_path.endswith('.py'):
                continue
            basename = os.path.basename(rel_path)
            if 'test' in basename.lower():
                continue
            # Skip __init__.py? Usually importing package works if __init__ exists.
            # We try to import the module path.
            modules.append(rel_path)

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='subprocess_import',
                detail='No importable non-test modules found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        env = os.environ.copy()
        current_pythonpath = env.get('PYTHONPATH', '')
        new_paths = [workdir, src_dir]
        if current_pythonpath:
            new_paths.append(current_pythonpath)
        env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # We need to import each module. 
        # Converting path to module name:
        # src/foo/bar.py -> foo.bar
        # foo/bar.py -> foo.bar

        import_errors = []
        module_not_found_errors = []

        for rel_path in modules:
            # Determine module name
            # Remove .py
            mod_path = rel_path[:-3]
            # Replace / with .
            mod_name = mod_path.replace('/', '.').replace('\\', '.')

            # If it's in src/, the module name is relative to src/
            if rel_path.startswith('src/'):
                mod_name = rel_path[4:-3].replace('/', '.').replace('\\', '.')

            # Skip if it's just __init__
            if mod_name.endswith('.__init__'):
                mod_name = mod_name[:-9]
            if mod_name == '__init__':
                continue

            if not mod_name:
                continue

            # Run subprocess to import
            code = f"import {mod_name}"
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the error is about the module itself not being found, it's a failure.
                        # If it's about a dependency, it's skipped.
                        # Simple heuristic: if the module name is in the error, it's a failure.
                        # If it's a different name, it might be third party.
                        # Spec: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
                        # "If any module fails with a syntax or runtime error, return FAILED"

                        # Let's check if the error is specifically about the module we tried to import
                        # or a dependency.
                        # If we import 'foo' and 'foo' imports 'bar' and 'bar' is missing, 
                        # stderr will say ModuleNotFoundError: No module named 'bar'

                        # If the error is about the module itself:
                        if f"No module named '{mod_name}'" in stderr or f"No module named \"{mod_name}\"" in stderr:
                            import_errors.append(f"{mod_name}: Module not found")
                        else:
                            # Likely a third-party dependency
                            module_not_found_errors.append(f"{mod_name}: {stderr.strip()}")
                    else:
                        import_errors.append(f"{mod_name}: {stderr.strip()}")

            except subprocess.TimeoutExpired:
                import_errors.append(f"{mod_name}: Timeout")
            except Exception as e:
                import_errors.append(f"{mod_name}: {e}")

        duration = time.time() - start

        if import_errors:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='subprocess_import',
                detail='; '.join(import_errors),
                duration_s=duration,
                evidence={'errors': import_errors}
            )

        if module_not_found_errors:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='subprocess_import',
                detail='Missing third-party dependencies',
                duration_s=duration,
                evidence={'missing_deps': module_not_found_errors}
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='subprocess_import',
            detail=f"Imported {len(modules)} modules",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = []
        for rel_path in authored:
            if not rel_path.endswith('.py'):
                continue
            basename = os.path.basename(rel_path)
            if 'test' in basename.lower():
                test_files.append(rel_path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest_or_unittest',
                detail='No test files found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        env = os.environ.copy()
        current_pythonpath = env.get('PYTHONPATH', '')
        new_paths = [workdir, src_dir]
        if current_pythonpath:
            new_paths.append(current_pythonpath)
        env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Try pytest first
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)

            # Run pytest
            # We run pytest on the test files
            # Use -q for quiet, --tb=short for short tracebacks
            cmd = [self.python_executable, '-m', 'pytest', '-q', '--tb=short'] + test_files

            result = subprocess.run(
                cmd,
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start

            if result.returncode == 0:
                return GateResult(
                    name='tests',
                    status=PASSED,
                    method='pytest',
                    detail='All tests passed',
                    duration_s=duration
                )
            else:
                # Check for ModuleNotFoundError in output
                if 'ModuleNotFoundError' in result.stdout or 'ModuleNotFoundError' in result.stderr:
                    # If tests failed due to missing modules, skip
                    # But pytest might report collection errors.
                    # If it's a collection error due to missing module, it's skipped.
                    # If tests ran and failed, it's failed.
                    # Heuristic: if "collected 0 items" and ModuleNotFoundError, skip.
                    if "collected 0 items" in result.stdout or "no tests ran" in result.stdout.lower():
                         return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='pytest',
                            detail='Tests skipped due to missing dependencies',
                            duration_s=duration,
                            evidence={'output': result.stdout + result.stderr}
                        )

                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests failed',
                    duration_s=duration,
                    evidence={'stdout': result.stdout, 'stderr': result.stderr}
                )

        except Exception:
            # Fallback to stdlib unittest
            pass

        # Stdlib fallback
        # We need to run a script that imports each test file and runs tests
        # This is complex to do in one subprocess for multiple files with different paths.
        # Let's run a single subprocess that executes a generated script.

        script_lines = [
            "import sys",
            "import unittest",
            "import importlib",
            "import os",
            "import traceback",
            "",
            "def run_tests():",
            "    loader = unittest.TestLoader()",
            "    suite = unittest.TestSuite()",
            "    errors = []",
            "    skipped = False",
            "    ",
            "    test_files = " + repr(test_files),
            "    ",
            "    for tf in test_files:",
            "        try:",
            "            # Convert path to module name",
            "            mod_path = tf[:-3]",
            "            if mod_path.startswith('src/'):",
            "                mod_name = mod_path[4:].replace('/', '.').replace('\\\\', '.')",
            "            else:",
            "                mod_name = mod_path.replace('/', '.').replace('\\\\', '.')",
            "            ",
            "            if mod_name.endswith('.__init__'):",
            "                mod_name = mod_name[:-9]",
            "            ",
            "            if not mod_name:",
            "                continue",
            "                ",
            "            mod = importlib.import_module(mod_name)",
            "            suite.addTests(loader.loadTestsFromModule(mod))",
            "        except ModuleNotFoundError as e:",
            "            skipped = True",
            "            errors.append(f'ModuleNotFound: {e}')",
            "        except Exception as e:",
            "            errors.append(f'ImportError: {tf}: {e}')",
            "            ",
            "    if skipped and not suite.countTestCases():",
            "        print('SKIPPED')",
            "        return 0",
            "        ",
            "    if errors:",
            "        print('ERRORS:', errors)",
            "        return 1",
            "        ",
            "    runner = unittest.TextTestRunner(verbosity=0)",
            "    result = runner.run(suite)",
            "    if result.wasSuccessful():",
            "        return 0",
            "    else:",
            "        return 1",
            "",
            "sys.exit(run_tests())"
        ]

        script_content = "\n".join(script_lines)

        try:
            result = subprocess.run(
                [self.python_executable, '-c', script_content],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start

            if result.returncode == 0:
                if 'SKIPPED' in result.stdout:
                    return GateResult(
                        name='tests',
                        status=SKIPPED,
                        method='unittest_fallback',
                        detail='Tests skipped due to missing dependencies',
                        duration_s=duration
                    )
                return GateResult(
                    name='tests',
                    status=PASSED,
                    method='unittest_fallback',
                    detail='All tests passed',
                    duration_s=duration
                )
            else:
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFound' in result.stdout:
                    return GateResult(
                        name='tests',
                        status=SKIPPED,
                        method='unittest_fallback',
                        detail='Tests skipped due to missing dependencies',
                        duration_s=duration,
                        evidence={'stderr': result.stderr}
                    )
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='unittest_fallback',
                    detail='Tests failed',
                    duration_s=duration,
                    evidence={'stdout': result.stdout, 'stderr': result.stderr}
                )

        except Exception as e:
            return GateResult(
                name='tests',
                status=FAILED,
                method='unittest_fallback',
                detail=f'Error running tests: {e}',
                duration_s=time.time() - start
            )

    def _gate_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        py_files = self._get_python_files(workdir, authored)

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span',
            'start_span',
            'get_tracer',
            'get_tracer_provider',
            'set_tracer_provider',
            'get_meter'
        }

        for rel_path in py_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                tree = ast.parse(content)

                for node in ast.walk(tree):
                    # Check for import opentelemetry
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls
                    if isinstance(node, ast.Call):
                        func = node.func
                        # Direct call: get_tracer()
                        if isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True
                        # Attribute call: tracer.start_span() or otel.get_tracer()
                        elif isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True

            except Exception:
                continue

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(
                name='telemetry',
                status=PASSED,
                method='ast_analysis',
                detail='OpenTelemetry import and usage found',
                duration_s=duration
            )

        if not has_import:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No OpenTelemetry import found',
                duration_s=duration
            )

        if not has_call:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='OpenTelemetry imported but no tracer/span calls found',
                duration_s=duration
            )

        return GateResult(
            name='telemetry',
            status=FAILED,
            method='ast_analysis',
            detail='Telemetry requirements not met',
            duration_s=duration
        )
